package com.cpf.core.common.database; public class CpfReadRoutingRuntimePolicy {public record Snapshot(boolean enabled,long maxReplicaLagMillis,long readAfterWriteMillis){}private Snapshot current;private final boolean fail;public CpfReadRoutingRuntimePolicy(Snapshot s,boolean f){current=s;fail=f;}public Snapshot current(){return current;}public Snapshot replace(boolean e,long l,long w){if(fail)throw new IllegalArgumentException("bad");return current=new Snapshot(e,l,w);}}
